def isRationalEqual(s, t):
    from fractions import Fraction

    def parse(x):
        if '.' not in x:
            return Fraction(int(x))
        intpart, frac = x.split('.')
        value = Fraction(int(intpart) if intpart else 0)
        if '(' in frac:
            nonrep, rep = frac.split('(')
            rep = rep.rstrip(')')
        else:
            nonrep, rep = frac, ''
        a = len(nonrep)
        if nonrep:
            value += Fraction(int(nonrep), 10 ** a)
        if rep:
            b = len(rep)
            # repeating block starting after `a` non-repeating digits
            value += Fraction(int(rep), (10 ** b - 1) * (10 ** a))
        return value

    return parse(s) == parse(t)
